import{_ as e,o as r,c as i,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2020-03-16 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2020-03-16 :: Ceph Orchestration Meeting","date":"2020-03-16T00:00:00.000Z","updated":"2020-04-04T00:00:00.000Z","tags":["Ceph","分布式存储","开发","测试","项目管理"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-03-16_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2020/2020-03-16_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),o={name:"posts/2020/2020-03-16_-_-_Ceph_Orchestration_Meeting.md"};function a(n,t,s,h,g,_){return r(),i("div",null,[...t[0]||(t[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><ul><li><strong>日期</strong>: 2020年3月16日</li><li><strong>参与者</strong>: Lily及其他未明确提及的成员</li><li><strong>背景</strong>: 由于学校关闭，孩子们在家，可能会有一些背景噪音。</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>全球疫情情况</strong></p><ul><li>讨论了各国因疫情采取的封锁措施，如意大利、法国等地的封锁情况。</li><li>提到了美国和欧洲国家对非必要商业活动的关闭，仅保留药店和超市等基本服务。</li></ul></li><li><p><strong>Ceph开发相关</strong></p><ul><li><strong>开发者峰会</strong>: 讨论了即将到来的开发者峰会的时间安排和内容。</li><li><strong>OSD Remover功能</strong>: 讨论了OSD Remover的实现和使用场景，特别是替换和重用OSD ID的需求和挑战。</li><li><strong>项目管理标签</strong>: 提出了为项目功能添加标签以更好地组织和跟踪功能的建议。</li><li><strong>Sefie DM相关</strong>: 讨论了Sefie DM的功能和未来的改进方向。</li></ul></li><li><p><strong>OCS在裸金属环境中的测试</strong></p><ul><li>讨论了在裸金属环境中使用OCS（OpenShift Container Storage）的挑战和需求，包括网络隔离、多OSD每NVMe设备配置等问题。</li><li>提出了对现有OCS配置和功能的改进建议，以更好地支持高性能的裸金属环境。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li><strong>开发者峰会</strong>: 需要确定具体的时间和议程。</li><li><strong>OSD Remover功能</strong>: 需要进一步讨论和明确其使用场景和实现细节。</li><li><strong>项目管理标签</strong>: 同意需要改进项目管理和功能跟踪的方法。</li><li><strong>OCS在裸金属环境中的测试</strong>: 需要进一步研究和解决相关的技术问题。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>开发者峰会</strong>: 安排具体的时间和议程，确保所有相关人员都能参与。</li><li><strong>OSD Remover功能</strong>: 继续讨论并明确其使用场景和实现细节。</li><li><strong>项目管理标签</strong>: 开始实施标签系统，以更好地组织和跟踪项目功能。</li><li><strong>OCS在裸金属环境中的测试</strong>: 继续研究和解决相关的技术问题。</li></ul><h4 id="其他备注" tabindex="-1">其他备注 <a class="header-anchor" href="#其他备注" aria-label="Permalink to &quot;其他备注&quot;">​</a></h4><ul><li>会议中提到了全球疫情对日常生活和工作的影响，强调了团队成员之间的相互理解和支持。</li><li>会议记录中包含了一些技术细节和讨论，需要相关领域的专业人员进一步分析和处理。</li></ul>',11)])])}const c=e(o,[["render",a]]);export{u as __pageData,c as default};
